    fputs("static VC_MAYBE_UNUSED bool vc_terminal_get_cursor_position(VcArray *data)\n{\n", file);
    fputs("    if (data == NULL || data->rank != 1 || data->element_size != sizeof(int32_t) || data->length < 2) return false;\n", file);
