    fputs("            values[1] = (int32_t)(row - 1);\n", file);
    fputs("            ok = true;\n", file);
    fputs("        }\n", file);
    fputs("    }\n", file);
    fputs("    if (tcsetattr(STDIN_FILENO, TCSANOW, &original) != 0) return false;\n", file);
    fputs("    return ok;\n", file);
