    fputs("static VC_MAYBE_UNUSED bool vc_terminal_set_title(VcString *title)\n{\n", file);
    fputs("    if (title == NULL) return false;\n", file);
    fputs("#ifdef _WIN32\n", file);
    fputs("    if (title->length > (size_t)INT_MAX) return false;\n", file);
    fputs("    int chars = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, title->data, (int)title->length, NULL, 0);\n", file);
    fputs("    if (chars < 0) return false;\n", file);
    fputs("    WCHAR *buffer = malloc(((size_t)chars + 1u) * sizeof(WCHAR));\n", file);
    fputs("    if (buffer == NULL) return false;\n", file);
    fputs("    if (chars > 0 && MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, title->data, (int)title->length, buffer, chars) != chars) { free(buffer); return false; }\n", file);
    fputs("    buffer[chars] = L'\\0';\n", file);
    fputs("    BOOL ok = SetConsoleTitleW(buffer);\n", file);
    fputs("    free(buffer);\n", file);
    fputs("    return ok != 0;\n", file);
    fputs("#else\n", file);
    fputs("    if (isatty(STDOUT_FILENO) == 0) return false;\n", file);
    fputs("    if (fwrite(\"\\033]0;\", 1u, 4u, stdout) != 4u) return false;\n", file);
    fputs("    if (title->length != 0u && fwrite(title->data, 1u, title->length, stdout) != title->length) return false;\n", file);
    fputs("    if (fwrite(\"\\007\", 1u, 1u, stdout) != 1u) return false;\n", file);
    fputs("    return fflush(stdout) == 0;\n", file);
    fputs("#endif\n", file);
    fputs("}\n\n", file);

    fputs("enum\n", file);
    fputs("{\n", file);
    fputs("    VC_TERMINAL_EVENT_CHARACTER = 0,\n", file);
    fputs("    VC_TERMINAL_EVENT_ENTER = 1,\n", file);
    fputs("    VC_TERMINAL_EVENT_BACKSPACE = 2,\n", file);
    fputs("    VC_TERMINAL_EVENT_TAB = 3,\n", file);
    fputs("    VC_TERMINAL_EVENT_ESCAPE = 4,\n", file);
    fputs("    VC_TERMINAL_EVENT_UP = 5,\n", file);
    fputs("    VC_TERMINAL_EVENT_DOWN = 6,\n", file);
    fputs("    VC_TERMINAL_EVENT_LEFT = 7,\n", file);
    fputs("    VC_TERMINAL_EVENT_RIGHT = 8,\n", file);
    fputs("    VC_TERMINAL_EVENT_HOME = 9,\n", file);
    fputs("    VC_TERMINAL_EVENT_END = 10,\n", file);
    fputs("    VC_TERMINAL_EVENT_INSERT = 11,\n", file);
    fputs("    VC_TERMINAL_EVENT_DELETE = 12,\n", file);
    fputs("    VC_TERMINAL_EVENT_PAGE_UP = 13,\n", file);
    fputs("    VC_TERMINAL_EVENT_PAGE_DOWN = 14,\n", file);
    fputs("    VC_TERMINAL_EVENT_F1 = 15\n", file);
    fputs("};\n", file);
    fputs("\n", file);
    fputs("static VC_MAYBE_UNUSED bool vc_terminal_store_event(VcArray *data, int32_t scalar, int32_t kind, int32_t modifiers)\n", file);
    fputs("{\n", file);
    fputs("    if (data == NULL || data->rank != 1 || data->element_size != sizeof(int32_t) || data->length < 3) return false;\n", file);
    fputs("    int32_t *values = (int32_t *)data->data;\n", file);
    fputs("    values[0] = scalar;\n", file);
    fputs("    values[1] = kind;\n", file);
    fputs("    values[2] = modifiers;\n", file);
    fputs("    return true;\n", file);
    fputs("}\n", file);
    fputs("\n", file);
    fputs("static VC_MAYBE_UNUSED int32_t vc_terminal_modifier_bits_from_xterm(int32_t parameter)\n", file);
    fputs("{\n", file);
    fputs("    switch (parameter)\n", file);
    fputs("    {\n", file);
    fputs("        case 2: return 2;\n", file);
    fputs("        case 3: return 1;\n", file);
    fputs("        case 4: return 3;\n", file);
    fputs("        case 5: return 4;\n", file);
    fputs("        case 6: return 6;\n", file);
    fputs("        case 7: return 5;\n", file);
    fputs("        case 8: return 7;\n", file);
    fputs("        default: return 0;\n", file);
    fputs("    }\n", file);
    fputs("}\n", file);
    fputs("\n", file);
    fputs("#ifndef _WIN32\n", file);
    fputs("static VC_MAYBE_UNUSED int vc_terminal_fgetc_timeout(const struct termios *raw, int timeout_tenths)\n", file);
    fputs("{\n", file);
    fputs("    struct termios timed = *raw;\n", file);
    fputs("    timed.c_cc[VMIN] = timeout_tenths < 0 ? 1 : 0;\n", file);
    fputs("    timed.c_cc[VTIME] = timeout_tenths < 0 ? 0 : (cc_t)timeout_tenths;\n", file);
    fputs("    if (tcsetattr(STDIN_FILENO, TCSANOW, &timed) != 0) return EOF;\n", file);
    fputs("    int value = fgetc(stdin);\n", file);
    fputs("    if (value == EOF) clearerr(stdin);\n", file);
    fputs("    return value;\n", file);
    fputs("}\n", file);
    fputs("\n", file);
    fputs("static VC_MAYBE_UNUSED bool vc_terminal_read_utf8_scalar_posix(const struct termios *raw, int first, int32_t *scalar)\n", file);
    fputs("{\n", file);
    fputs("    uint8_t bytes[4];\n", file);
    fputs("    size_t length = 1u;\n", file);
    fputs("    bytes[0] = (uint8_t)first;\n", file);
    fputs("    size_t expected = 0u;\n", file);
    fputs("    if (bytes[0] < 0x80u) expected = 1u;\n", file);
    fputs("    else if (bytes[0] >= 0xc2u && bytes[0] <= 0xdfu) expected = 2u;\n", file);
    fputs("    else if (bytes[0] >= 0xe0u && bytes[0] <= 0xefu) expected = 3u;\n", file);
    fputs("    else if (bytes[0] >= 0xf0u && bytes[0] <= 0xf4u) expected = 4u;\n", file);
    fputs("    else return false;\n", file);
    fputs("    while (length < expected)\n", file);
    fputs("    {\n", file);
    fputs("        int next = vc_terminal_fgetc_timeout(raw, -1);\n", file);
    fputs("        if (next == EOF) return false;\n", file);
    fputs("        bytes[length++] = (uint8_t)next;\n", file);
    fputs("    }\n", file);
    fputs("    size_t offset = 0u;\n", file);
    fputs("    uint32_t value = 0u;\n", file);
    fputs("    if (!vc_utf8_decode_one((const char *)bytes, length, &offset, &value) || offset != length) return false;\n", file);
    fputs("    *scalar = (int32_t)value;\n", file);
    fputs("    return true;\n", file);
    fputs("}\n", file);
    fputs("\n", file);
    fputs("static VC_MAYBE_UNUSED bool vc_terminal_parse_csi_posix(const struct termios *raw, int first, VcArray *data)\n", file);
    fputs("{\n", file);
    fputs("    char sequence[16];\n", file);
    fputs("    size_t length = 0u;\n", file);
    fputs("    sequence[length++] = (char)first;\n", file);
    fputs("    while (length < sizeof(sequence))\n", file);
    fputs("    {\n", file);
    fputs("        unsigned char last = (unsigned char)sequence[length - 1u];\n", file);
    fputs("        if (last >= 0x40u && last <= 0x7eu) break;\n", file);
    fputs("        int next = vc_terminal_fgetc_timeout(raw, 1);\n", file);
    fputs("        if (next == EOF) break;\n", file);
    fputs("        sequence[length++] = (char)next;\n", file);
    fputs("    }\n", file);
    fputs("    if (length == 0u) return vc_terminal_store_event(data, 0, VC_TERMINAL_EVENT_ESCAPE, 0);\n", file);
    fputs("\n", file);
    fputs("    char final = sequence[length - 1u];\n", file);
    fputs("    int32_t numbers[3] = {0, 0, 0};\n", file);
    fputs("    size_t number_count = 0u;\n", file);
    fputs("    int32_t current = 0;\n", file);
    fputs("    bool have_current = false;\n", file);
    fputs("    for (size_t i = 0u; i + 1u < length && number_count < 3u; i++)\n", file);
    fputs("    {\n", file);
    fputs("        char ch = sequence[i];\n", file);
    fputs("        if (ch >= '0' && ch <= '9')\n", file);
    fputs("        {\n", file);
    fputs("            current = current * 10 + (int32_t)(ch - '0');\n", file);
    fputs("            have_current = true;\n", file);
    fputs("        }\n", file);
    fputs("        else if (ch == ';')\n", file);
    fputs("        {\n", file);
    fputs("            numbers[number_count++] = have_current ? current : 0;\n", file);
    fputs("            current = 0;\n", file);
    fputs("            have_current = false;\n", file);
    fputs("        }\n", file);
    fputs("    }\n", file);
    fputs("    if (have_current && number_count < 3u) numbers[number_count++] = current;\n", file);
    fputs("    int32_t modifiers = number_count >= 2u ? vc_terminal_modifier_bits_from_xterm(numbers[1]) : 0;\n", file);
    fputs("\n", file);
    fputs("    int32_t kind = -1;\n", file);
    fputs("    if (final == 'A') kind = VC_TERMINAL_EVENT_UP;\n", file);
    fputs("    else if (final == 'B') kind = VC_TERMINAL_EVENT_DOWN;\n", file);
    fputs("    else if (final == 'C') kind = VC_TERMINAL_EVENT_RIGHT;\n", file);
    fputs("    else if (final == 'D') kind = VC_TERMINAL_EVENT_LEFT;\n", file);
    fputs("    else if (final == 'H') kind = VC_TERMINAL_EVENT_HOME;\n", file);
    fputs("    else if (final == 'F') kind = VC_TERMINAL_EVENT_END;\n", file);
    fputs("    else if (final == '~')\n", file);
    fputs("    {\n", file);
    fputs("        int32_t code = number_count > 0u ? numbers[0] : 0;\n", file);
    fputs("        if (code == 1 || code == 7) kind = VC_TERMINAL_EVENT_HOME;\n", file);
    fputs("        else if (code == 2) kind = VC_TERMINAL_EVENT_INSERT;\n", file);
    fputs("        else if (code == 3) kind = VC_TERMINAL_EVENT_DELETE;\n", file);
    fputs("        else if (code == 4 || code == 8) kind = VC_TERMINAL_EVENT_END;\n", file);
    fputs("        else if (code == 5) kind = VC_TERMINAL_EVENT_PAGE_UP;\n", file);
    fputs("        else if (code == 6) kind = VC_TERMINAL_EVENT_PAGE_DOWN;\n", file);
    fputs("        else if (code == 11) kind = VC_TERMINAL_EVENT_F1;\n", file);
    fputs("        else if (code == 12) kind = VC_TERMINAL_EVENT_F1 + 1;\n", file);
    fputs("        else if (code == 13) kind = VC_TERMINAL_EVENT_F1 + 2;\n", file);
    fputs("        else if (code == 14) kind = VC_TERMINAL_EVENT_F1 + 3;\n", file);
    fputs("        else if (code == 15) kind = VC_TERMINAL_EVENT_F1 + 4;\n", file);
    fputs("        else if (code == 17) kind = VC_TERMINAL_EVENT_F1 + 5;\n", file);
    fputs("        else if (code == 18) kind = VC_TERMINAL_EVENT_F1 + 6;\n", file);
    fputs("        else if (code == 19) kind = VC_TERMINAL_EVENT_F1 + 7;\n", file);
    fputs("        else if (code == 20) kind = VC_TERMINAL_EVENT_F1 + 8;\n", file);
    fputs("        else if (code == 21) kind = VC_TERMINAL_EVENT_F1 + 9;\n", file);
    fputs("        else if (code == 23) kind = VC_TERMINAL_EVENT_F1 + 10;\n", file);
    fputs("        else if (code == 24) kind = VC_TERMINAL_EVENT_F1 + 11;\n", file);
    fputs("    }\n", file);
    fputs("    if (kind < 0) return vc_terminal_store_event(data, 0, VC_TERMINAL_EVENT_ESCAPE, 0);\n", file);
    fputs("    return vc_terminal_store_event(data, 0, kind, modifiers);\n", file);
    fputs("}\n", file);
    fputs("#endif\n", file);
    fputs("\n", file);
    fputs("#ifdef _WIN32\n", file);
    fputs("/* Keep repeat records and surrogate pairs serialized across concurrent readers. */\n", file);
    fputs("static SRWLOCK vc_terminal_input_lock = SRWLOCK_INIT;\n", file);
    fputs("static KEY_EVENT_RECORD vc_terminal_pending_key;\n", file);
    fputs("static unsigned int vc_terminal_pending_repeat;\n", file);
    fputs("static VC_MAYBE_UNUSED bool vc_terminal_windows_key(const KEY_EVENT_RECORD *key)\n", file);
    fputs("{\n", file);
    fputs("    WORD code = key->wVirtualKeyCode;\n", file);
    fputs("    return key->bKeyDown && (key->uChar.UnicodeChar != 0 ||\n", file);
    fputs("        code == VK_UP || code == VK_DOWN || code == VK_LEFT || code == VK_RIGHT ||\n", file);
    fputs("        code == VK_HOME || code == VK_END || code == VK_INSERT || code == VK_DELETE ||\n", file);
    fputs("        code == VK_PRIOR || code == VK_NEXT || (code >= VK_F1 && code <= VK_F12));\n", file);
    fputs("}\n", file);
    fputs("static VC_MAYBE_UNUSED bool vc_terminal_windows_read_key(KEY_EVENT_RECORD *key)\n", file);
    fputs("{\n", file);
    fputs("    if (vc_terminal_pending_repeat != 0u)\n", file);
    fputs("    {\n", file);
    fputs("        *key = vc_terminal_pending_key;\n", file);
    fputs("        vc_terminal_pending_repeat--;\n", file);
    fputs("        return true;\n", file);
    fputs("    }\n", file);
    fputs("    HANDLE input = GetStdHandle(STD_INPUT_HANDLE);\n", file);
    fputs("    INPUT_RECORD record;\n", file);
    fputs("    DWORD actual = 0;\n", file);
    fputs("    while (ReadConsoleInputW(input, &record, 1, &actual) && actual == 1)\n", file);
    fputs("    {\n", file);
    fputs("        if (record.EventType != KEY_EVENT || !vc_terminal_windows_key(&record.Event.KeyEvent)) continue;\n", file);
    fputs("        *key = record.Event.KeyEvent;\n", file);
    fputs("        vc_terminal_pending_key = *key;\n", file);
    fputs("        vc_terminal_pending_repeat = key->wRepeatCount > 1 ? key->wRepeatCount - 1u : 0u;\n", file);
    fputs("        return true;\n", file);
    fputs("    }\n", file);
    fputs("    return false;\n", file);
    fputs("}\n", file);
    fputs("static VC_MAYBE_UNUSED bool vc_terminal_windows_read_event(VcArray *data)\n", file);
    fputs("{\n", file);
    fputs("    if (_isatty(_fileno(stdin)) == 0) return false;\n", file);
    fputs("    KEY_EVENT_RECORD key;\n", file);
    fputs("    if (!vc_terminal_windows_read_key(&key)) return false;\n", file);
    fputs("    int32_t modifiers = 0;\n", file);
    fputs("    if ((key.dwControlKeyState & (LEFT_ALT_PRESSED | RIGHT_ALT_PRESSED)) != 0) modifiers |= 1;\n", file);
    fputs("    if ((key.dwControlKeyState & SHIFT_PRESSED) != 0) modifiers |= 2;\n", file);
    fputs("    if ((key.dwControlKeyState & (LEFT_CTRL_PRESSED | RIGHT_CTRL_PRESSED)) != 0) modifiers |= 4;\n", file);
    fputs("    uint32_t scalar = (uint32_t)key.uChar.UnicodeChar;\n", file);
    fputs("    int32_t kind = VC_TERMINAL_EVENT_CHARACTER;\n", file);
    fputs("    if (scalar == 0)\n", file);
    fputs("    {\n", file);
    fputs("        WORD code = key.wVirtualKeyCode;\n", file);
    fputs("        if (code == VK_UP) kind = VC_TERMINAL_EVENT_UP;\n", file);
    fputs("        else if (code == VK_DOWN) kind = VC_TERMINAL_EVENT_DOWN;\n", file);
    fputs("        else if (code == VK_LEFT) kind = VC_TERMINAL_EVENT_LEFT;\n", file);
    fputs("        else if (code == VK_RIGHT) kind = VC_TERMINAL_EVENT_RIGHT;\n", file);
    fputs("        else if (code == VK_HOME) kind = VC_TERMINAL_EVENT_HOME;\n", file);
    fputs("        else if (code == VK_END) kind = VC_TERMINAL_EVENT_END;\n", file);
    fputs("        else if (code == VK_INSERT) kind = VC_TERMINAL_EVENT_INSERT;\n", file);
    fputs("        else if (code == VK_DELETE) kind = VC_TERMINAL_EVENT_DELETE;\n", file);
    fputs("        else if (code == VK_PRIOR) kind = VC_TERMINAL_EVENT_PAGE_UP;\n", file);
    fputs("        else if (code == VK_NEXT) kind = VC_TERMINAL_EVENT_PAGE_DOWN;\n", file);
    fputs("        else if (code >= VK_F1 && code <= VK_F12) kind = VC_TERMINAL_EVENT_F1 + (code - VK_F1);\n", file);
    fputs("        else return false;\n", file);
    fputs("    }\n", file);
    fputs("    if (scalar >= 0xd800u && scalar <= 0xdbffu)\n", file);
    fputs("    {\n", file);
    fputs("        KEY_EVENT_RECORD low;\n", file);
    fputs("        if (!vc_terminal_windows_read_key(&low) || low.uChar.UnicodeChar < 0xdc00 || low.uChar.UnicodeChar > 0xdfff) return false;\n", file);
    fputs("        scalar = 0x10000u + ((scalar - 0xd800u) << 10u) + ((uint32_t)low.uChar.UnicodeChar - 0xdc00u);\n", file);
    fputs("    }\n", file);
    fputs("    if (scalar == 13u || scalar == 10u) kind = VC_TERMINAL_EVENT_ENTER;\n", file);
    fputs("    else if (scalar == 8u || scalar == 127u) kind = VC_TERMINAL_EVENT_BACKSPACE;\n", file);
    fputs("    else if (scalar == 9u) kind = VC_TERMINAL_EVENT_TAB;\n", file);
    fputs("    else if (scalar == 27u) kind = VC_TERMINAL_EVENT_ESCAPE;\n", file);
    fputs("    return vc_terminal_store_event(data, kind == VC_TERMINAL_EVENT_CHARACTER ? (int32_t)scalar : (kind == VC_TERMINAL_EVENT_ENTER ? 13 : (kind == VC_TERMINAL_EVENT_TAB ? 9 : (kind == VC_TERMINAL_EVENT_BACKSPACE ? 8 : (kind == VC_TERMINAL_EVENT_ESCAPE ? 27 : 0)))), kind, modifiers);\n", file);
    fputs("}\n", file);
    fputs("\n", file);
    fputs("static VC_MAYBE_UNUSED int32_t vc_terminal_windows_key_available(void)\n", file);
    fputs("{\n", file);
    fputs("    if (vc_terminal_pending_repeat != 0u) return 1;\n", file);
    fputs("    HANDLE input = GetStdHandle(STD_INPUT_HANDLE);\n", file);
    fputs("    INPUT_RECORD record;\n", file);
    fputs("    DWORD actual = 0;\n", file);
    fputs("    for (;;)\n", file);
    fputs("    {\n", file);
    fputs("        if (!PeekConsoleInputW(input, &record, 1, &actual)) return -1;\n", file);
    fputs("        if (actual == 0) return 0;\n", file);
    fputs("        if (record.EventType == KEY_EVENT && vc_terminal_windows_key(&record.Event.KeyEvent)) return 1;\n", file);
    fputs("        if (!ReadConsoleInputW(input, &record, 1, &actual) || actual != 1) return -1;\n", file);
    fputs("    }\n", file);
    fputs("}\n", file);
    fputs("\n", file);
    fputs("#endif\n", file);
    fputs("\n", file);
    fputs("static VC_MAYBE_UNUSED bool vc_terminal_read_event(VcArray *data)\n", file);
    fputs("{\n", file);
    fputs("    if (data == NULL || data->rank != 1 || data->element_size != sizeof(int32_t) || data->length < 3) return false;\n", file);
    fputs("#ifdef _WIN32\n", file);
    fputs("    AcquireSRWLockExclusive(&vc_terminal_input_lock);\n", file);
    fputs("    bool result = vc_terminal_windows_read_event(data);\n", file);
    fputs("    ReleaseSRWLockExclusive(&vc_terminal_input_lock);\n", file);
    fputs("    return result;\n", file);
    fputs("#else\n", file);
    fputs("    if (isatty(STDIN_FILENO) == 0) return false;\n", file);
    fputs("    struct termios original;\n", file);
    fputs("    if (tcgetattr(STDIN_FILENO, &original) != 0) return false;\n", file);
    fputs("    struct termios raw = original;\n", file);
    fputs("    raw.c_lflag &= (tcflag_t)~(ICANON | ECHO);\n", file);
    fputs("    raw.c_iflag &= (tcflag_t)~(ICRNL | IXON);\n", file);
    fputs("    raw.c_cc[VMIN] = 1;\n", file);
    fputs("    raw.c_cc[VTIME] = 0;\n", file);
    fputs("    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) return false;\n", file);
    fputs("\n", file);
    fputs("    bool result = false;\n", file);
    fputs("    int first = vc_terminal_fgetc_timeout(&raw, -1);\n", file);
    fputs("    if (first != EOF)\n", file);
    fputs("    {\n", file);
    fputs("        int32_t modifiers = 0;\n", file);
    fputs("        if (first == 27)\n", file);
    fputs("        {\n", file);
    fputs("            int next = vc_terminal_fgetc_timeout(&raw, 1);\n", file);
    fputs("            if (next == EOF)\n", file);
    fputs("                result = vc_terminal_store_event(data, 27, VC_TERMINAL_EVENT_ESCAPE, 0);\n", file);
    fputs("            else if (next == '[')\n", file);
    fputs("            {\n", file);
    fputs("                int initial = vc_terminal_fgetc_timeout(&raw, 1);\n", file);
    fputs("                result = initial == EOF ? vc_terminal_store_event(data, 27, VC_TERMINAL_EVENT_ESCAPE, 0) : vc_terminal_parse_csi_posix(&raw, initial, data);\n", file);
    fputs("            }\n", file);
    fputs("            else if (next == 'O')\n", file);
    fputs("            {\n", file);
    fputs("                int final = vc_terminal_fgetc_timeout(&raw, 1);\n", file);
    fputs("                int32_t kind = final == 'P' ? VC_TERMINAL_EVENT_F1 : (final == 'Q' ? VC_TERMINAL_EVENT_F1 + 1 : (final == 'R' ? VC_TERMINAL_EVENT_F1 + 2 : (final == 'S' ? VC_TERMINAL_EVENT_F1 + 3 : -1)));\n", file);
    fputs("                result = kind >= 0 ? vc_terminal_store_event(data, 0, kind, 0) : vc_terminal_store_event(data, 27, VC_TERMINAL_EVENT_ESCAPE, 0);\n", file);
    fputs("            }\n", file);
    fputs("            else\n", file);
    fputs("            {\n", file);
    fputs("                int32_t scalar = 0;\n", file);
    fputs("                if (vc_terminal_read_utf8_scalar_posix(&raw, next, &scalar))\n", file);
    fputs("                    result = vc_terminal_store_event(data, scalar, VC_TERMINAL_EVENT_CHARACTER, 1);\n", file);
    fputs("            }\n", file);
    fputs("        }\n", file);
    fputs("        else if (first == 13 || first == 10)\n", file);
    fputs("            result = vc_terminal_store_event(data, 13, VC_TERMINAL_EVENT_ENTER, 0);\n", file);
    fputs("        else if (first == 8 || first == 127)\n", file);
